import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.C8R-a4p3.js";var i=JSON.parse(`{"title":"Databases — Modeled and Tuned","description":"PostgreSQL, MySQL, MongoDB, Redis, Firebase — schema design, query tuning and honest trade-offs.","frontmatter":{"title":"Databases — Modeled and Tuned","description":"PostgreSQL, MySQL, MongoDB, Redis, Firebase — schema design, query tuning and honest trade-offs."},"headers":[],"relativePath":"en/skills/databases/index.md","filePath":"en/skills/databases/index.md"}`),a={name:`en/skills/databases/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="databases-—-modeled-and-tuned" tabindex="-1">Databases — Modeled and Tuned <a class="header-anchor" href="#databases-—-modeled-and-tuned" aria-label="Permalink to “Databases — Modeled and Tuned”">​</a></h1><p>Most performance problems I meet are database problems wearing a frontend costume. I design schemas deliberately, measure before optimizing, and pick engines by workload instead of fashion.</p><h2 id="engine-choices-i-actually-make" tabindex="-1">Engine choices I actually make <a class="header-anchor" href="#engine-choices-i-actually-make" aria-label="Permalink to “Engine choices I actually make”">​</a></h2><table tabindex="0"><thead><tr><th>Engine</th><th>When I choose it</th></tr></thead><tbody><tr><td>PostgreSQL</td><td>Default OLTP: panels, APIs, anything with relations and constraints.</td></tr><tr><td>MySQL / MariaDB</td><td>Shared-hosting realities and legacy stacks.</td></tr><tr><td>MongoDB</td><td>Document-shaped, rapidly evolving data — session vaults, logs.</td></tr><tr><td>Redis</td><td>Caching, queues, rate limiting, session state.</td></tr><tr><td>Firebase / Supabase</td><td>Zero-ops products and prototypes that still need auth + data.</td></tr></tbody></table><ul><li><strong>Schema design</strong> — normalization where integrity matters, deliberate denormalization where reads dominate.</li><li><strong>Query tuning</strong> — EXPLAIN plans, index strategy, N+1 hunting.</li><li><strong>Migrations</strong> — versioned, reversible, rehearsed on staging.</li><li><strong>Backups</strong> — automated, tested, and actually restorable (the only kind that count).</li></ul>`,5)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};